<?php require_once '../config/auth.php';$page_title='Reports';$base='../';$won=$pdo->query("SELECT COUNT(*) c,COALESCE(SUM(amount),0) total FROM deals WHERE stage='won'")->fetch();$lost=$pdo->query("SELECT COUNT(*) c,COALESCE(SUM(amount),0) total FROM deals WHERE stage='lost'")->fetch();$pipeline=$pdo->query("SELECT stage,COUNT(*) deals,COALESCE(SUM(amount),0) value FROM deals WHERE stage NOT IN('won','lost') GROUP BY stage")->fetchAll();include '../partials/header.php';?><div class="row g-3"><div class="col-md-4"><div class="cardx"><small class="text-muted">Won revenue</small><div class="metric">$<?=number_format($won['total'],2)?></div><span><?=$won['c']?> deals</span></div></div><div class="col-md-4"><div class="cardx"><small class="text-muted">Lost value</small><div class="metric">$<?=number_format($lost['total'],2)?></div><span><?=$lost['c']?> deals</span></div></div><div class="col-md-4"><div class="cardx"><small class="text-muted">Win rate</small><div class="metric"><?=($won['c']+$lost['c'])?round($won['c']/($won['c']+$lost['c'])*100):0?>%</div><span>Won / closed</span></div></div></div><div class="cardx mt-4"><h5>Pipeline report</h5><table class="table mt-3"><thead><tr><th>Stage</th><th>Deals</th><th>Pipeline value</th></tr></thead><tbody><?php foreach($pipeline as $r):?><tr><td><?=e(ucfirst($r['stage']))?></td><td><?=$r['deals']?></td><td>$<?=number_format($r['value'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php include '../partials/footer.php';?>